{"probes": [{"obligation_id": "OB-007", "strategy": "example", "rationale": "If the implementation wrongly treats the non-final '*' in 's3:*Object' as a wildcard, it will match 's3:GetObject' and return Allow, whereas the spec requires it be treated as a literal asterisk matching only the exact string 's3:*Object'.", "code": "import impl


def test_non_final_asterisk_is_literal_not_wildcard():
    policies = [{
        "Effect": "Allow",
        "Action": ["s3:*Object"],
        "Resource": ["*"],
    }]

    literal_request = {
        "action": "s3:*Object",
        "resource": "arn:aws:s3:::bucket/key",
    }
    wildcard_attempt_request = {
        "action": "s3:GetObject",
        "resource": "arn:aws:s3:::bucket/key",
    }

    literal_result = impl.authorize(literal_request, policies)
    wildcard_result = impl.authorize(wildcard_attempt_request, policies)

    # exact literal match against 's3:*Object' must be allowed
    assert literal_result == "Allow"
    # 's3:GetObject' must NOT match, since the non-final '*' is literal, not a wildcard
    assert wildcard_result != "Allow"
"}]}
